const upsertJoin = `-- name: UpsertJoin :exec
INSERT INTO community_activity_joins (activity_id, user_id, status, joined_at, left_at)
VALUES ($1, $2, $3, $4, NULL)
ON CONFLICT (activity_id, user_id) DO UPDATE SET status = EXCLUDED.status, joined_at = EXCLUDED.joined_at, left_at = NULL
`

type UpsertJoinParams struct {
	ActivityID int64
	UserID     int64
	Status     string
	JoinedAt   time.Time
}

func (q *Queries) UpsertJoin(ctx context.Context, arg UpsertJoinParams) error {
	_, err := q.db.Exec(ctx, upsertJoin,
		arg.ActivityID,
		arg.UserID,
		arg.Status,
		arg.JoinedAt,
	)
	return err
}
